std::vector<int> numbers;

// Add elements (dynamic growth)
numbers.push_back(10);
numbers.emplace_back(20);

// Size and Capacity
size_t s = numbers.size();
size_t cap = numbers.capacity(); // Current allocated memory

// Access elements
int first = numbers[0]; // No bounds check
int second = numbers.at(1); // Bounds check (throws std::out_of_range)

// Initialization list
std::vector<std::string> names = {"A", "B", "C"};

// Iteration (range-based loop)
for (const auto& n : numbers) { /* process n */ }
